<?php declare(strict_types=1); require __DIR__.'/../config/config.php'; $db=db(); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){try{$category=trim((string)($_POST['category']??''));$description=trim((string)($_POST['description']??''));$amount=(float)($_POST['amount']??0);if($category==='')throw new RuntimeException('Enter an expense category.');if($amount<=0)throw new RuntimeException('Enter a valid expense amount.');$db->prepare('INSERT INTO expenses(category,description,amount) VALUES(?,?,?)')->execute([$category,$description?:null,$amount]);audit_log('expense_created','Expense: '.$category.' · Rs. '.number_format($amount,2));header('Location: expenses.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}$rows=$db->query('SELECT * FROM expenses ORDER BY id DESC LIMIT 200')->fetchAll();$today=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE DATE(created_at)=CURDATE()")->fetchColumn();$month=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE YEAR(created_at)=YEAR(CURDATE()) AND MONTH(created_at)=MONTH(CURDATE())")->fetchColumn();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expenses</title><link rel="stylesheet" href="style.css"></head><body><header><div class="brand">💊 <?=e(APP_NAME)?></div><nav><a href="index.php">Dashboard</a><a href="pos.php">POS</a><a href="inventory.php">Inventory</a><a class="active" href="manage.php">Management</a></nav></header><main><div class="page-title"><div><div class="eyebrow">FINANCE</div><h1>Expenses</h1><p>Record operating expenses and keep them available for reports.</p></div></div><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['saved'])):?><div class="success">✓ Expense recorded.</div><?php endif;?><div class="cards"><div><span>Today's expenses</span><b>Rs. <?=money($today)?></b></div><div><span>This month</span><b>Rs. <?=money($month)?></b></div></div><section class="panel"><h2>Add Expense</h2><form method="post" class="grid"><label>Category<input name="category" placeholder="Rent, electricity, salary, transport..." required></label><label>Description<input name="description" placeholder="Optional details"></label><label>Amount<input name="amount" type="number" min="0.01" step="0.01" required></label><button class="btn">Save Expense</button></form></section><section class="panel"><h2>Expense History</h2><table><tr><th>Date</th><th>Category</th><th>Description</th><th>Amount</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><b><?=e($r['category'])?></b></td><td><?=e($r['description']??'—')?></td><td>Rs. <?=money((float)$r['amount'])?></td></tr><?php endforeach;?></table></section></main></body></html>